// This file is generated by AI.

//! 自动播放的时序语义：`-keep` / `-next` / `-continue` 与 `wait` 对后续语句的影响。
//!
//! 引擎里动画演出的 `blockingAuto = !keep`（`autoPlay.ts` 会等阻塞演出结束才推进），
//! `-continue` 在演出结束时主动继续，`wait`/intro/视频结束时也会结算其它非 hold 演出。
//! 导出按同一套语义排时间线：非 `-next` 语句要等所有阻塞演出结束；`-next` 链内不等待。

use std::fs;
use std::path::{Path, PathBuf};

use webgal_video_export::{
    config::ExportConfig,
    plan::Plan,
    project::Project,
    script::{ChoicePolicy, compile},
};

fn write(root: &Path, relative: &str, bytes: &[u8]) {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, bytes).expect("write fixture");
}

/// 用一段内联脚本编译计划；`bg.png` 从 minimal fixture 复制过来（只测时序，不渲染）。
fn compile_scene(scene: &str) -> Plan {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Keep;\n");
    write(root, "game/scene/start.txt", scene.as_bytes());
    if scene.contains("bg.png") {
        let source = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/minimal/game/background/bg.png");
        let bytes = fs::read(source).expect("read bg fixture");
        write(root, "game/background/bg.png", &bytes);
    }
    let project = Project::open(root).expect("open project");
    let config = ExportConfig::default();
    let policy = ChoicePolicy::new(&config.choices);
    compile(&project, &config, &policy).expect("compile")
}

fn starts(plan: &Plan) -> Vec<u64> {
    plan.texts.iter().map(|text| text.start_us).collect()
}

#[test]
fn animation_without_keep_blocks_auto_play() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=2000;\nsay:hi;\nend;\n",
    );
    // 非 keep 的演出让自动播放等 2s，之后才轮到第一句。
    assert_eq!(starts(&plan), vec![2_000_000]);
}

#[test]
fn keep_does_not_delay_the_next_line() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=2000 -keep;\nsay:hi;\nend;\n",
    );
    // keep 的演出不阻塞自动播放：台词立刻出现，动画在后台继续。
    assert_eq!(starts(&plan), vec![0]);
}

#[test]
fn continue_advances_at_the_animation_end() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=2000 -continue;\nsay:hi;\nend;\n",
    );
    // `-continue`: 演出自然结束时立即继续，不等自动播放的停留时间。
    assert_eq!(starts(&plan), vec![2_000_000]);
}

#[test]
fn keep_with_continue_still_advances_at_the_end() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=2000 -keep -continue;\nsay:hi;\nend;\n",
    );
    // `-keep` 不阻塞自动播放，但 `-continue` 的 goNextWhenOver 仍然在演出结束时触发。
    assert_eq!(starts(&plan), vec![2_000_000]);
}

#[test]
fn next_chain_blocks_after_the_chain() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=8000 -next;\n\
         say:first;\nsay:second;\nend;\n",
    );
    let starts = starts(&plan);
    // 第一句在链内立即出现；链结束后自动播放仍被 8s 的动画阻塞。
    assert_eq!(starts[0], 0);
    assert_eq!(starts[1], 8_000_000);
}

#[test]
fn next_chain_with_keep_does_not_block_after_the_chain() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=8000 -keep -next;\n\
         say:first;\nsay:second;\nend;\n",
    );
    let starts = starts(&plan);
    assert_eq!(starts[0], 0);
    // keep 不阻塞：第二句就是第一句正常结束的时间，明显早于 8s 的动画。
    assert_eq!(starts[1], plan.texts[0].end_us);
    assert!(starts[1] < 8_000_000);
}

#[test]
fn wait_settles_a_running_animation() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=8000 -next;\n\
         wait:100;\nsay:hi;\nend;\n",
    );
    // wait 的 goNextWhenOver 会结算其它非 hold 演出，所以不必等满 8s。
    assert_eq!(starts(&plan), vec![100_000]);
}

#[test]
fn change_bg_blocks_auto_play_until_the_transition_ends() {
    let plan = compile_scene("changeBg:bg.png -duration=8000;\nsay:hi;\nend;\n");
    assert_eq!(starts(&plan), vec![8_000_000]);
}

#[test]
fn parallel_animations_block_until_the_longest_ends() {
    let plan = compile_scene(
        "setTransform:{\"alpha\":0.5} -target=stage-main -duration=3000 -parallel -next;\n\
         setTransform:{\"alpha\":0.6} -target=stage-main -duration=1000 -parallel -next;\n\
         say:first;\nsay:second;\nend;\n",
    );
    let starts = starts(&plan);
    assert_eq!(starts[0], 0);
    // 两条 parallel 演出都阻塞自动播放，取最晚的 3s。
    assert_eq!(starts[1], 3_000_000);
}
